"""Render only audited actual results; no estimates of completed updates."""
import json,pathlib,hashlib
R=pathlib.Path(__file__).resolve().parents[1];O=R/'execution';read=lambda p:json.loads(p.read_text())
a=read(O/'optimizer-audit.json');c=read(O/'comparison.json');control=read(R.parent/'round16/execution/optimizer-audit.json');p=read(R/'policy.json');selection=read(R/'training-unit-selection.json');m=read(O/'new-manual.json');j=read(O/'export-rounding.json')
assert a['actualCompletedUpdates']==10000 and a['optimizerCounters']==[20000]
assert a['initialWeightedDevelopmentNllPerByte']==control['initialWeightedDevelopmentNllPerByte']
better=a['bestWeightedDevelopmentNllPerByte']<p['nllSuccessThreshold'];new=c['models']['new'];old=c['models']['old']
goal=dict(actualCompletedUpdates=10000,requestedUpdates=10000,nllImprovedOverMatchedRound16=better,controlNll=p['nllSuccessThreshold'],newNll=a['bestWeightedDevelopmentNllPerByte'],developmentLanguageGatePassed=new['gatePassed'],progressCriterionMet=better or new['gatePassed'],naturalJapaneseEstablished=False,newTestGenerated=False,publicModelChanged=False)
(O/'progress-goal.json').write_text(json.dumps(goal,indent=2)+'\n')
counts=selection['siteCounts'];table='\n'.join(f"| {site} | {x['total']} | {x['selected']} |" for site,x in counts.items());reasons='\n'.join('- `'+x['id']+'`: '+x['reason'] for x in m['rows'])
text=f"""# Round17 — 現代TRAINの段落完結性対照\n\n実10,000更新を完了。共通開発NLL={a['bestWeightedDevelopmentNllPerByte']:.9f}、初文{new['firstSentencePasses']}/17、非ループ{new['nonLoopOutputs']}/17、全文意味{new['meaningfulFullOutputs']}/17。既存言語ゲート={new['gatePassed']}。NLL改善と自然な日本語能力の成立は区別する。公開モデルとWebサイトは変更していない。\n\n## 変更と対照\n\nRound16と同じRound11最新step10000の重み・AdamW・Torch RNG・Python RNGを整合して開始した兄弟対照。Round16の採用best重みと最新optimizerを混ぜない。今回の変更は現代ジャンルTRAIN内の機械的な段落選別のみ。句点等2個以上、閉じ括弧を除いた末尾が文終端、日本語文字50%以上。青空文庫は変更なし。閾値は学習前に固定し、開発生成による選別を行わない。原文の書き換え、新しい原文、多様性の追加、人間の独立品質認定とは扱わない。完全重複の事前監査では除外可能量が少なく、段落完結性を検証対象に選んだ。\n\n| ジャンル | 元TRAIN単位 | 残した単位 |\n|---|---:|---:|\n{table}\n\nTRAIN以外を選別/学習に追加していない。既存出典の利用条件・SHA・文書foldを維持し、Round10の既知短文重複等の限界も引き継ぐ。全3ビューをunit単位で一緒に選別し、元のtoken byte列とtarget maskingを保持する。ジャンル比率、通常/Glyph/ランダム文字境界40/30/30、独自語彙5455、8層dim192/context256/dropout.1、batch8、FP32/CPU2、seed2049系譜、LR{p['learningRate']:.17g}固定、weight_decay.05/clip1、検証500ごとを対照と一致させた。語彙・重み・教師文は外部モデルから取得していない。\n\n## 実更新・再現\n\n実追加更新={a['actualCompletedUpdates']}。親optimizer counter10000→最新20000。最新保持系譜={a['latestWeightLineageUpdates']}、採用追加step={a['selectedStep']}、採用保持系譜={a['selectedWeightLineageUpdates']}。親からの兄弟対照であり、Round16からさらに10,000更新したモデルとは記録しない。最新重み/optimizer/RNGはcheckpoint.pt、推論用採用重みはselected-weights.pt/model.js。再開は未完了時のみrun.sh --resume、最新整合状態を使う。全moment・勾配・SHA、初期一致、sampling周辺比、RNG replay、target数をexecution JSONに保存した。\n\ncheckpoint SHA `{a['checkpointSha256']}`\n\n採用重み SHA `{a['selectedWeightsSha256']}`\n\n追加token={a['seenTargetTokens']}、UTF8 byte={a['seenTargetUtf8Bytes']}、訓練経過={a['elapsedTrainingSeconds']:.2f}秒。lossはCSV/metrics/train.logへ保存。保存step/実optimizer counterで完了を確認し、予定値から推測していない。\n\n## 共通開発比較\n\n| モデル | 最良NLL/byte | 初文 | 非ループ | 全文意味 | Python/JS |\n|---|---:|---:|---:|---:|---:|\n| Round16 対照 | {control['bestWeightedDevelopmentNllPerByte']:.9f} | {old['firstSentencePasses']}/17 | {old['nonLoopOutputs']}/17 | {old['meaningfulFullOutputs']}/17 | {old['matchingSequences']}/17 |\n| Round17 | {a['bestWeightedDevelopmentNllPerByte']:.9f} | {new['firstSentencePasses']}/17 | {new['nonLoopOutputs']}/17 | {new['meaningfulFullOutputs']}/17 | {new['matchingSequences']}/17 |\n\n共通開発NLL改善={better}、既存言語ゲート={new['gatePassed']}。どちらも最良点選択の単一seed・既存露出開発。新TEST・独立人間評価・未見一般化は未実証。初文80%、非ループ90%、全文意味80%を全scope/groupに要求する既存厳格ゲートは変更していない。同じ17書き出し、全語彙greedy、max192、真EOS停止、Python1threadで比較。無修正全文とtokenをFULL_GENERATIONS.md/JSONに保存した。\n\n## 全文判定理由\n\n{reasons}\n\n## 数値と原因\n\n生FP32対export一致={j['matchingSequences']}/17。Python/JSの新最大参照logit誤差={new['maxReferenceLogitError']:.9g}、許容2e-4不変。既知Round10 near-tie分岐は旧報告に残っており、今回の一致で否定しない。\n\n容量: 466万parameterを保持しており容量効果は未切り分け。全文失敗だけで大規模化の効果を断定しない。\n\nデータ: 今回は完結性proxyの選別効果だけを測定。原文の多様性や意味の接続を保証せず、公式説明・API文書の偏りは残る。割合だけを変更したRound13–15の失敗と区別する。\n\n境界: 40/30/30を保持、Round12の文字境界除去でも全文0/17だった。今回から境界単独原因とは断定できない。\n\nLR/optimizer: 同じ初期moment/RNG・終端LRで対照と比較。数値有限・counter一致は適正なLRの証明ではない。\n\ncontext: 256を保持し容量/長文制約は未切り分け。初文段階の崩れはcontext長だけでは説明しにくい。\n\n学習不足/過学習: 全推移を保存し、最良/終端の差と固定TRAIN/dev標本を診断。標本gapやNLLだけでは自由生成改善も過学習も確定しない。\n\n推論誤差: 生FP32/export/JS比較はこの17入力の診断。数値分岐が全言語失敗の原因とは扱わない。\n\n評価: exposed17、非blind assistant判定、短文の意味/固有名詞/事実性混同の限界あり。独立再評価と事前固定した未露出holdoutが必要。既存ゲートは緩和しない。\n\n次の候補は、選別では補えない人間の現代日本語原文の文間接続・多様性をTRAIN限定で追加する一因子対照。今回その新規原文追加は実行していない。学習回数や容量の追加だけを自動的に選ばない。成果物のSHA/サイズはartifact-manifest.json、コード/入力の事前SHAはsource-manifest.json。\n"""
(R/'RESULTS.md').write_text(text);print(json.dumps(goal))
